-- Replace only unchanged starter privacy copy; preserve customised blocks and layout.
WITH replacements(id, old_body, new_body, new_heading) AS (
 VALUES
  ($policy$privacy-s0$policy$, $policy$<p> At Ace Paddlers, we strongly believe in protecting consumer privacy. That's why we only ask you for information related to the services we provide. We never sell, rent, share, trade or give away any of your personal information to anyone. This privacy policy describes what information we collect from you, how it is used and what security measures we take to protect it. </p>$policy$, $policy$<p>Ace Paddlers collects information needed to respond to enquiries and provide bookings. We do not sell or rent personal information. We share necessary details with guides, accommodation partners, payment, hosting, email, and WhatsApp providers supporting your request.</p>$policy$, $policy$Protecting Consumer Privacy$policy$),
  ($policy$privacy-s1$policy$, $policy$<p> In order for us to provide an attractive and easy-to-navigate website, we must occasionally use our visitors' IP addresses for purposes such as optimising our use of search engines or diagnosing problems with our server. Furthermore, to better tailor our website and product offerings to our customers, we may use analytics tools to collect information on how visitors navigate our website. Cookies are used to collect aggregated data that allows us to see the origins of web traffic, amount of visitors, visitors' operating systems, browser types, etc. This data does not personally identify you in any way. You can choose not to accept cookies by disabling them in the settings of your web browser. </p>$policy$, $policy$<p>Essential cookies and browser storage support sign-in, security, and privacy preferences. Your choice is saved as ap_cookie_consent_v1 in local storage. Optional first-party analytics starts only after Allow analytics. It records page paths, referring sites, campaigns, and booking or enquiry events. The session identifier (ap_sid) and attribution (ap_attr) live in session storage for the tab. Essential only declines analytics; Cookie settings in the footer lets you change your choice and clear this tab’s analytics identifiers. Server logs and form protection may process IP addresses.</p><p>Interactive maps load on request. Maps, sign-in, payments, externally hosted fonts, and images connect to their providers, which receive connection information and may use storage or cookies. Their privacy notices apply.</p>$policy$, $policy$Cookies, Storage & Analytics$policy$),
  ($policy$privacy-s2$policy$, $policy$<p> When you book a tour on our website, we require contact information, such as your name and e-mail address and, in some cases, partial or full postal address or telephone number. This information is only used to contact you with information about your tour. In rare cases, we may need to share your contact information with tour guides who are responsible for the booked tour. Otherwise, we do not sell or share this information with any third parties. </p> <p> At the time of booking, we may also ask you for payment. Online payments are processed securely by our payment partner — your card, UPI, or bank details are entered directly with the payment gateway and are never stored on our servers. We use the utmost level of online security to safeguard your personal data. </p>$policy$, $policy$<p>We use contact and guest details to respond to enquiries and arrange bookings. Necessary information may be shared with guides, accommodation partners, payment, hosting, email, and WhatsApp service providers. If you select the optional booking-help checkbox, we may contact you about an unfinished booking. Otherwise, contact details are sent when you submit the form.</p><p>Razorpay processes online payments. Card, UPI, and bank details are entered with the gateway and are not stored on our servers. We retain payment references and status to manage bookings.</p>$policy$, $policy$Bookings & Payments$policy$),
  ($policy$privacy-s3$policy$, $policy$<p> Our website is protected by the utmost level of online security, meaning your personal data is safe with us. All transactions on the site are secured with industry-standard encryption, and any data we gather from users is securely stored and safeguarded by the best firewalls available. </p>$policy$, $policy$<p>We use access controls and encrypted connections to protect information. No online service can guarantee absolute security. We retain records as needed to provide services, handle support and disputes, and meet applicable record-keeping obligations. Contact us about retention or deletion.</p>$policy$, $policy$Online Security$policy$),
  ($policy$privacy-s4$policy$, $policy$<p> You can ask us, at any time, to see what personal information we hold about you, correct it, or delete it. To make a request, contact us at info@acepaddlers.com or call/WhatsApp . Full instructions for requesting deletion of your data are on our Data Deletion page. </p>$policy$, $policy$<p>To request access, correction, or deletion, email <a href="mailto:info@acepaddlers.com">info@acepaddlers.com</a>. See our <a href="/data-deletion">Data Deletion instructions</a>.</p>$policy$, $policy$Your Rights & Data Deletion$policy$),
  ($policy$privacy-s6$policy$, $policy$<p> Ace Paddlers, T. Shettigeri, Virajpet, Kodagu — 571218, Karnataka, India. Email: info@acepaddlers.com · Phone/WhatsApp: </p> <p> See also our Cancellation Policy. </p>$policy$, $policy$<p>Ace Paddlers, T. Shettigeri, Virajpet, Kodagu — 571218, Karnataka, India. Email <a href="mailto:info@acepaddlers.com">info@acepaddlers.com</a> or <a href="/contact">contact us</a>.</p><p>See our <a href="/terms-and-conditions">Terms &amp; Conditions</a> and <a href="/cancellation-policy">Cancellation Policy</a>.</p>$policy$, $policy$Contact Us$policy$)
)
UPDATE pages p
SET data = jsonb_set(p.data, '{content}', (
  SELECT jsonb_agg(
    CASE WHEN b.value->'props'->>'body' = r.old_body
      THEN jsonb_set(b.value, '{props}', (b.value->'props') || jsonb_build_object('body', r.new_body, 'heading', r.new_heading))
      ELSE b.value END ORDER BY b.ordinality)
  FROM jsonb_array_elements(p.data->'content') WITH ORDINALITY AS b(value, ordinality)
  LEFT JOIN replacements r ON b.value->'props'->>'id' = r.id
)), updated_at = now()
WHERE p.slug = 'privacy' AND jsonb_typeof(p.data->'content') = 'array'
  AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(p.data->'content') b
    JOIN replacements r ON b->'props'->>'id' = r.id AND b->'props'->>'body' = r.old_body
  );

--> statement-breakpoint
-- The saved About hero references an unavailable upload. Reuse its existing
-- hand-built fallback; leave any subsequently edited image untouched.
UPDATE pages
SET data = replace(data::text,
  '"/media/img/3aad9dad-5637-4727-a3ea-f415f788921d.jpg"',
  '"/images/badra-rafting-2.jpg"')::jsonb,
  updated_at = now()
WHERE slug = 'about' AND data::text LIKE '%"/media/img/3aad9dad-5637-4727-a3ea-f415f788921d.jpg"%';
